from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = set()
        self.loans = {}          # book_id -> (user, borrow_day)
        self.fines = {}          # user -> unpaid amount
        self.histories = {}      # user -> list of book_ids in borrow order
        self.titles = {}         # book_id -> title

    def add_book(self, book_id: str, title: str = "") -> None:
        self.books.add(book_id)
        self.titles[book_id] = title

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError("Unknown book")
        if book_id in self.loans:
            raise ValueError("Book is already borrowed")
        # Requirement 3: a user with unpaid fines may borrow, but holds at most one book
        if self.fines.get(user, 0) > 0:
            if any(u == user for u, _ in self.loans.values()):
                raise ValueError("User with unpaid fines may hold at most one book")
        self.loans[book_id] = (user, day)
        self.histories.setdefault(user, []).append(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.loans:
            raise ValueError("Book is not borrowed")
        borrower, borrow_day = self.loans[book_id]
        if borrower != user:
            raise ValueError("User did not borrow this book")

        del self.loans[book_id]

        due_day = borrow_day + timedelta(days=self.loan_days)
        fine = 0.0
        if day > due_day:
            # Count only weekdays (Mon-Fri) between due_day (exclusive) and day (inclusive)
            delay_days = 0
            d = due_day + timedelta(days=1)
            while d <= day:
                if d.weekday() < 5:
                    delay_days += 1
                d += timedelta(days=1)
            fine = delay_days * self.daily_fine

        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self.fines[user] = 0.0

    def available(self) -> list[str]:
        return sorted(self.books - set(self.loans))

    def history(self, user: str) -> list[str]:
        return list(self.histories.get(user, []))

    def title(self, book_id: str) -> str:
        return self.titles.get(book_id, "")
```

